// The option check from async-sema (MIT): pauseFn and resumeFn must be given
// together, tested with `^` over two booleans. Bitwise operators convert
// booleans with ToNumber.
'use strict';
function isFn(x) {
  return typeof x == 'function';
}
class Sema {
  constructor(capacity, { pauseFn, resumeFn } = {}) {
    if (isFn(pauseFn) ^ isFn(resumeFn)) throw new Error('pauseFn and resumeFn must be both set for pausing');
    this.capacity = capacity;
    this.pausable = isFn(pauseFn) & isFn(resumeFn);
  }
}
function bits(values) {
  var yes = values.length > 0;
  var no = values.length < 0;
  var flags = 0;
  var count = 0;
  for (var v of values) {
    flags = flags | (v > 0);
    count = count + ((v > 1) & 1);
  }
  return [
    yes ^ no, yes ^ yes, yes & no, yes | no, no | no, yes & 3, 2 | yes,
    yes << 3, yes >> 0, no >>> 0, -1 >>> yes, 5 ^ yes, no ^ 7,
    typeof (yes ^ no), flags, count,
  ].join(' ');
}
module.exports = { Sema: Sema, bits: bits };
